This fixes a bug that was introduced in commit
23daf151dc4ba9d32eeb3c45a215ed44f8c5423d.

diff --git a/src/terminal/terminal.c b/src/terminal/terminal.c
index f689f777..b6f52b20 100644
--- a/src/terminal/terminal.c
+++ b/src/terminal/terminal.c
@@ -84,6 +84,10 @@ void term_init(void)
         term_init_fail("'TERM' not set");
     }

+    if (!term_mode_init()) {
+        term_init_fail("tcgetattr: %s", strerror(errno));
+    }
+
     if (getenv("DTE_FORCE_TERMINFO")) {
         if (term_init_terminfo(term)) {
             return;
@@ -92,10 +96,6 @@ void term_init(void)
         }
     }

-    if (!term_mode_init()) {
-        term_init_fail("tcgetattr: %s", strerror(errno));
-    }
-
     switch (get_term_type(term)) {
     case TERM_XTERM:
         terminal = xterm;
-- 
